M['records']['teacherreview']={'kind':'faculty_comment','date':'2026-10-31','studentKey':'','staffId':'X:one','sectionKey':'','subjectId':'','notes':'Please report teaching progress','outcome':'','visibility':'general','authorId':'principal','authorName':'Principal','authorRole':'principal','updatedAt':1}
