 page.evaluate("location.hash='tab=academics&class=X'");page.get_by_role('heading',name='Students academic history',exact=True).wait_for();page.get_by_role('button',name='Total fail · Critical + Fail: 2 out of 2 students',exact=True).wait_for();assert float(page.locator('.large-statistics strong').first.evaluate('(e)=>parseFloat(getComputedStyle(e).fontSize)'))>=38
