 page.evaluate("location.hash='class=XII'");page.get_by_role('combobox',name='XII stream',exact=True).select_option('Science');page.get_by_role('button',name='Secure pass: 1 out of 1 students',exact=True).wait_for();assert page.locator('.section-zones .zone-card').count()==1;page.get_by_role('button',name='Open academic history',exact=True).click();page.get_by_role('combobox',name='Academic stream',exact=True).wait_for();assert page.get_by_role('combobox',name='Academic stream',exact=True).input_value()=='Science'
 page.evaluate("location.hash='tab=teachers'");page.get_by_role('combobox',name='See my role / status',exact=True).select_option('X:one');page.get_by_role('heading',name='Teacher comments & Principal review',exact=True).wait_for();assert page.get_by_role('button',name='Classroom observation',exact=True).count()==0
 guest=b.new_page();guest.add_init_script('window.__guest=true');guest.route('https://www.gstatic.com/firebasejs/**',sdk);guest.route('**/api/staff-access',api);guest.on('pageerror',lambda e:errors.append(str(e)));guest.goto('http://127.0.0.1:8000/cbse-mission.html#staff=X%3Aone');guest.get_by_role('button',name='Reply to Principal with PIN',exact=True).click();guest.locator('[name=teacher-notes]').fill('Teaching progress reviewed');guest.locator('[name=teacher-pin]').fill('000');guest.get_by_role('button',name='Post comment with PIN',exact=True).click();guest.get_by_text('Wrong PIN',exact=True).wait_for();assert guest.locator('[name=teacher-notes]').input_value()=='Teaching progress reviewed';guest.locator('[name=teacher-pin]').fill('123');guest.get_by_role('button',name='Post comment with PIN',exact=True).click();guest.get_by_text('Teacher has replied',exact=True).wait_for();assert guest.locator('[name=teacher-pin]').input_value()==''
 for w in [360,768,1440]:
  guest.set_viewport_size({'width':w,'height':900});assert guest.evaluate('document.documentElement.scrollWidth<=innerWidth')
 assert not errors,errors
 print('PASS teacher totals/filter/section order, subject-only status and comments, full profile, XII stream statistics, large typography, role selector and PIN teacher reply on mobile/desktop')
 b.close()
